1	"use client";
2	
3	import { useState, useRef, useCallback, type MouseEvent, type TouchEvent } from 'react';
4	import type { PhotoMagicResult } from '../hooks/usePhotoMagic';
5	
6	interface ImageResultProps {
7	  result: PhotoMagicResult;
8	  onEditAgain: () => void;
9	  onReset: () => void;
10	}
11	
12	export function ImageResult({ result, onEditAgain, onReset }: ImageResultProps) {
13	  const [sliderPos, setSliderPos] = useState(50);
14	  const compareRef = useRef<HTMLDivElement>(null);
15	  const draggingRef = useRef(false);
16	
17	  const isCompare = !!result.originalImageUrl;
18	
19	  const updateSlider = useCallback((clientX: number) => {
20	    if (!compareRef.current) return;
21	    const rect = compareRef.current.getBoundingClientRect();
22	    const pct = Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100));
23	    setSliderPos(pct);
24	  }, []);
25	
26	  const onMouseDown = useCallback((e: MouseEvent) => {
27	    draggingRef.current = true;
28	    updateSlider(e.clientX);
29	  }, [updateSlider]);
30	
31	  const onMouseMove = useCallback((e: MouseEvent) => {
32	    if (draggingRef.current) updateSlider(e.clientX);
33	  }, [updateSlider]);
34	
35	  const onMouseUp = useCallback(() => { draggingRef.current = false; }, []);
36	
37	  const onTouchMove = useCallback((e: TouchEvent) => {
38	    if (e.touches[0]) updateSlider(e.touches[0].clientX);
39	  }, [updateSlider]);
40	
41	  const handleDownload = useCallback(() => {
42	    const a = document.createElement('a');
43	    a.href = result.imageUrl;
44	    a.download = `photo-magic-${Date.now()}.png`;
45	    a.click();
46	  }, [result.imageUrl]);
47	
48	  return (
49	    <div className="pm-result">
50	      <div className="pm-result__image-area">
51	        {isCompare ? (
52	          <div
53	            ref={compareRef}
54	            className="pm-compare"
55	            style={{
56	              '--clip-right': `${100 - sliderPos}%`,
57	              '--divider-x': `${sliderPos}%`,
58	            } as React.CSSProperties}
59	            onMouseDown={onMouseDown}
60	            onMouseMove={onMouseMove}
61	            onMouseUp={onMouseUp}
62	            onMouseLeave={onMouseUp}
63	            onTouchStart={(e) => { if (e.touches[0]) updateSlider(e.touches[0].clientX); }}
64	            onTouchMove={onTouchMove}
65	          >
66	            <img src={result.imageUrl} alt="Result" className="pm-compare__after" />
67	            <img src={result.originalImageUrl} alt="Original" className="pm-compare__before" />
68	            <div className="pm-compare__divider" />
69	            <div className="pm-compare__handle">⟷</div>
70	            <span className="pm-compare__label pm-compare__label--before">before</span>
71	            <span className="pm-compare__label pm-compare__label--after">after</span>
72	          </div>
73	        ) : (
74	          <img src={result.imageUrl} alt={result.prompt} className="pm-result__img" />
75	        )}
76	      </div>
77	
78	      <div className="pm-result__actions">
79	        <button className="pm-action-btn pm-action-btn--primary" onClick={handleDownload}>
80	          ↓ Download
81	        </button>
82	        <button className="pm-action-btn" onClick={onEditAgain}>
83	          Edit again
84	        </button>
85	        <button className="pm-action-btn" onClick={onReset}>
86	          Start fresh
87	        </button>
88	      </div>
89	    </div>
90	  );
91	}
