22	  const [brushSize, setBrushSize] = useState<BrushSize>('medium');
23	  const [strokes, setStrokes] = useState<Stroke[]>([]);
24	  const activeStrokeRef = useRef<Stroke | null>(null);
25	  const isDrawingRef = useRef(false);
26	  const imgDimRef = useRef({ w: 0, h: 0, scale: 1 });
27	  const rafRef = useRef<number>(0);
28	
29	  // Load image dimensions
30	  useEffect(() => {
31	    const img = new Image();
32	    img.onload = () => {
33	      imgDimRef.current.w = img.naturalWidth;
34	      imgDimRef.current.h = img.naturalHeight;
35	      fitCanvas();
36	    };
37	    img.src = imageUrl;
38	  }, [imageUrl]);
39	
40	  const fitCanvas = useCallback(() => {
41	    const canvas = canvasRef.current;
42	    const container = containerRef.current;
43	    if (!canvas || !container) return;
44	    const { w, h } = imgDimRef.current;
45	    if (!w || !h) return;
46	
