73	
74	    ctx.fillStyle = 'rgba(217, 79, 142, 0.4)';
75	    ctx.lineCap = 'round';
76	    ctx.lineJoin = 'round';
77	
78	    const scale = imgDimRef.current.scale;
79	
80	    for (const stroke of allStrokes) {
81	      if (!stroke?.points?.length) continue;
82	      ctx.beginPath();
83	      const r = (stroke.size * scale) / 2;
84	
85	      if (stroke.points.length === 1) {
86	        const p = stroke.points[0];
87	        ctx.arc(p.x * scale, p.y * scale, r, 0, Math.PI * 2);
88	        ctx.fill();
89	      } else {
90	        ctx.strokeStyle = 'rgba(217, 79, 142, 0.4)';
91	        ctx.lineWidth = stroke.size * scale;
92	        ctx.moveTo(stroke.points[0].x * scale, stroke.points[0].y * scale);
93	        for (let i = 1; i < stroke.points.length; i++) {
94	          ctx.lineTo(stroke.points[i].x * scale, stroke.points[i].y * scale);
95	        }
96	        ctx.stroke();
97	      }
98	    }
99	  }, [strokes]);
100	
101	  // Redraw whenever strokes change
102	  useEffect(() => { redraw(); }, [strokes, redraw]);
103	
104	  const getCanvasPoint = useCallback((e: PointerEvent): { x: number; y: number } | null => {
105	    const canvas = canvasRef.current;
106	    if (!canvas) return null;
107	    const rect = canvas.getBoundingClientRect();
108	    const scale = imgDimRef.current.scale;
